 async function get(key){let m;try{m=await check();}catch(e){errors.set(key,e);render();throw e;}const entry=m.resources[key];if(!entry?.path||!/^objects\/[a-f0-9]{64}\.json$/.test(entry.path)){const e=error(entry?.error?.kind||'pending',entry?.error?.status);errors.set(key,e);render();throw e;}try{let data=objects.get(entry.path);if(!data){if(!objectRequests.has(entry.path))objectRequests.set(entry.path,read(BASE+entry.path).then(v=>{objects.set(entry.path,v);return v;}).finally(()=>objectRequests.delete(entry.path)));data=await objectRequests.get(entry.path);}entries.set(key,{data,entry});errors.delete(key);render();return data;}catch(e){errors.set(key,e);render();if(entries.has(key))return entries.get(key).data;throw e;}}
 function status(keys){const list=keys.map(key=>{const stored=entries.get(key),latest=manifest?.resources[key]||stored?.entry,e=errors.get(key)||latest?.error;const age=latest?Date.now()-Date.parse(latest.lastSuccess):Infinity;const sourceAge=latest?.sourceTime?Date.now()-Date.parse(latest.sourceTime):0;return {key,available:!!stored||!!latest?.path,error:e?.kind||null,old:age>(latest?.ttlSeconds||3600)*2000||(!key.startsWith('archive')&&sourceAge>Math.max(3*3600000,(latest?.ttlSeconds||3600)*2000)),time:stored?.entry?.sourceTime||stored?.entry?.lastSuccess,updatedAt:stored?.entry?.lastSuccess||latest?.lastSuccess};});return {fresh:!transportError&&list.every(r=>r.available&&!r.error&&!r.old),available:list.some(r=>r.available),quota:list.some(r=>r.error==='quota'),transportError,items:list};}
 function updateText(time){const t=Date.parse(time);return Number.isFinite(t)?'Pembaruan terakhir '+new Date(t).toLocaleDateString('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',year:'numeric'})+' pukul '+new Date(t).toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit'})+' WIB':'Pembaruan terakhir belum tersedia';}
