 const api={get,check,status,message,mark,render,errorText:e=>e?.kind==='quota'?'Kuota sumber habis · menunggu pembaruan terjadwal.':e?.kind==='pending'?'Data tersimpan belum tersedia.':e?.kind==='invalid'?'Data sumber belum valid.':'Koneksi ke salinan data terganggu.'};scope.CachedData=api;
